public class ParallelSummer {

    public static long sum(int[] values) throws InterruptedException {
        long[] partial = new long[2];
        int mid = values.length / 2;
        Thread first = new Thread(() -> {
            long s = 0;
            for (int i = 0; i < mid; i++) {
                s += values[i];
            }
            partial[0] = s;
        });
        Thread second = new Thread(() -> {
            long s = 0;
            for (int i = mid; i < values.length; i++) {
                s += values[i];
            }
            partial[1] = s;
        });
        first.start();
        second.start();
        first.join();
        second.join();
        return partial[0] + partial[1];
    }
}
